css:
.aha-page-header{
  --aha-page-header-surface:var(--aha-white);
  --aha-page-header-ink:var(--aha-text-default);
  --aha-page-header-ink-secondary:var(--aha-text-secondary);
  --aha-page-header-eyebrow:var(--aha-color-primary);
  --aha-page-header-rule:var(--aha-border-default);
  --aha-page-header-accent:var(--aha-color-primary);
  --aha-page-header-focus:var(--aha-focus);
  container:aha-page-header / inline-size;
  font-family:var(--aha-font-product);
  background:var(--aha-page-header-surface);
  color:var(--aha-page-header-ink);
}
.aha-page-header--brand{
  --aha-page-header-surface:var(--aha-vivid-pink-100);
  --aha-page-header-ink:var(--aha-text-inverse);
  --aha-page-header-ink-secondary:var(--aha-text-inverse);
  --aha-page-header-eyebrow:var(--aha-text-inverse);
  --aha-page-header-rule:var(--aha-vivid-pink-dark);
  --aha-page-header-accent:var(--aha-white);
  --aha-page-header-focus:var(--aha-white);
}
.aha-page-header *{box-sizing:border-box}
:where(.aha-page-header) :is(h1,p,ul,form){margin:0;padding:0}
:where(.aha-page-header) ul{list-style:none}
.aha-page-header__inner{max-width:1280px;margin:0 auto;padding:var(--aha-space-64) var(--aha-space-32) 0}
.aha-page-header--no-tabs .aha-page-header__inner{padding-bottom:var(--aha-space-64)}
.aha-page-header__body{display:flex;flex-direction:column;gap:var(--aha-space-32)}
.aha-page-header__copy{max-width:768px}
.aha-page-header__eyebrow{
  margin-bottom:var(--aha-space-12);
  font-size:var(--aha-size-sm);font-weight:var(--aha-weight-semibold);
  letter-spacing:var(--aha-letter-spacing-subheadings);text-transform:uppercase;
  color:var(--aha-page-header-eyebrow);
}
.aha-page-header__title{
  font-size:var(--aha-size-h2);font-weight:var(--aha-weight-semibold);line-height:var(--aha-line-height-heading);
  letter-spacing:var(--aha-letter-spacing-headlines);
  color:var(--aha-page-header-ink);
}
.aha-page-header__text{
  margin-top:var(--aha-space-16);
  font-size:var(--aha-size-xl);font-weight:var(--aha-weight-regular);line-height:var(--aha-line-height-body);
  letter-spacing:var(--aha-letter-spacing-paragraph);
  color:var(--aha-page-header-ink-secondary);
}
.aha-page-header__actions{display:flex;flex-wrap:wrap;align-items:flex-start;gap:var(--aha-space-12)}
.aha-page-header__button{
  display:inline-flex;align-items:center;justify-content:center;
  height:var(--aha-control-height-button-lg);padding:0 var(--aha-space-20);
  border:1px solid transparent;border-radius:var(--aha-radius-default);
  font-family:inherit;font-size:var(--aha-size-l);font-weight:var(--aha-weight-regular);line-height:1;white-space:nowrap;
  text-decoration:none;cursor:pointer;
  transition:background-color var(--aha-motion-mid) var(--aha-ease-in-out),border-color var(--aha-motion-mid) var(--aha-ease-in-out),color var(--aha-motion-mid) var(--aha-ease-in-out);
}
.aha-page-header__button:focus-visible{outline:var(--aha-space-2) solid var(--aha-page-header-focus);outline-offset:var(--aha-space-2)}
.aha-page-header__button--primary{background:var(--aha-button-primary-bg);color:var(--aha-button-primary-text)}
.aha-page-header__button--primary:hover,.aha-page-header__button--primary:active{background:var(--aha-button-primary-bg-hover)}
.aha-page-header__button--secondary{background:var(--aha-button-default-bg);border-color:var(--aha-button-default-border);color:var(--aha-button-default-text)}
.aha-page-header__button--secondary:hover,.aha-page-header__button--secondary:active{background:var(--aha-button-default-bg-hover);border-color:var(--aha-button-default-border-hover);color:var(--aha-button-default-text-hover)}
.aha-page-header--brand .aha-page-header__button--primary{background:var(--aha-white);color:var(--aha-color-primary);box-shadow:var(--aha-button-elevate-primary)}
.aha-page-header--brand .aha-page-header__button--primary:hover,.aha-page-header--brand .aha-page-header__button--primary:active{background:var(--aha-white);color:var(--aha-color-primary-hover);box-shadow:var(--aha-button-elevate-primary-hover)}
.aha-page-header--brand .aha-page-header__button--secondary{background:transparent;border-color:var(--aha-white);color:var(--aha-text-inverse)}
.aha-page-header--brand .aha-page-header__button--secondary:hover,.aha-page-header--brand .aha-page-header__button--secondary:active{background:var(--aha-vivid-pink-dark);border-color:var(--aha-white);color:var(--aha-text-inverse)}
.aha-page-header__aside{width:100%;max-width:480px}
.aha-page-header__form{display:flex;flex-wrap:wrap;gap:var(--aha-space-12);width:100%;max-width:480px}
.aha-page-header__field{position:relative;display:flex;flex:1 1 240px;align-items:center;min-width:0}
.aha-page-header__field aha-icon{position:absolute;left:var(--aha-space-12);color:var(--aha-icon-muted);pointer-events:none}
.aha-page-header__input{
  width:100%;height:var(--aha-control-height-button-lg);padding:0 var(--aha-space-12);
  border:1px solid var(--aha-border-input);border-radius:var(--aha-radius-default);
  background:var(--aha-white);color:var(--aha-text-default);
  font-family:inherit;font-size:var(--aha-size-l);
  transition:border-color var(--aha-motion-mid) var(--aha-ease-in-out);
}
.aha-page-header__field aha-icon + .aha-page-header__input{padding-left:var(--aha-space-40)}
.aha-page-header__input::placeholder{color:var(--aha-text-placeholder);opacity:1}
.aha-page-header__input:hover{border-color:var(--aha-border-hover)}
.aha-page-header__input:focus{outline:none;border-color:var(--aha-border-focus)}
.aha-page-header__input:focus-visible{outline:var(--aha-space-2) solid var(--aha-page-header-focus);outline-offset:var(--aha-space-2)}
.aha-page-header__hint{margin-top:var(--aha-space-12);font-size:var(--aha-size-default);line-height:var(--aha-line-height-body);color:var(--aha-page-header-ink-secondary)}
.aha-page-header--brand .aha-page-header__hint{color:var(--aha-text-inverse)}
.aha-page-header__tabs{display:flex;flex-wrap:wrap;gap:var(--aha-space-8) var(--aha-space-24);margin-top:var(--aha-space-48);border-bottom:1px solid var(--aha-page-header-rule)}
.aha-page-header__tab{
  flex:none;padding:0 0 var(--aha-space-12);margin-bottom:-1px;
  border-bottom:var(--aha-space-2) solid transparent;
  font-size:var(--aha-size-l);font-weight:var(--aha-weight-regular);line-height:var(--aha-line-height-heading);
  color:var(--aha-page-header-ink-secondary);text-decoration:none;
  transition:color var(--aha-motion-mid) var(--aha-ease-in-out),border-color var(--aha-motion-mid) var(--aha-ease-in-out);
}
.aha-page-header__tab:hover{color:var(--aha-page-header-ink);border-bottom-color:var(--aha-page-header-rule)}
.aha-page-header__tab[aria-current="page"]{font-weight:var(--aha-weight-semibold);color:var(--aha-page-header-ink);border-bottom-color:var(--aha-page-header-accent)}
.aha-page-header__tab:focus-visible{outline:var(--aha-space-2) solid var(--aha-page-header-focus);outline-offset:var(--aha-space-2);border-radius:var(--aha-radius-xs)}
.aha-page-header--centre .aha-page-header__body{align-items:center;text-align:center}
.aha-page-header--centre .aha-page-header__copy{margin-inline:auto}
.aha-page-header--centre .aha-page-header__actions,.aha-page-header--centre .aha-page-header__form{justify-content:center}
.aha-page-header--centre .aha-page-header__tabs{justify-content:center}
.aha-page-header--space-between .aha-page-header__body{flex-direction:row;align-items:flex-end;justify-content:space-between;gap:var(--aha-space-48)}
.aha-page-header--space-between .aha-page-header__copy{flex:1 1 auto}
.aha-page-header--space-between .aha-page-header__aside{width:auto;max-width:none}
.aha-page-header--space-between .aha-page-header__actions,.aha-page-header--space-between .aha-page-header__form,.aha-page-header--space-between .aha-page-header__aside{flex:none}
.aha-page-header--space-between .aha-page-header__form{flex-wrap:nowrap;width:auto;max-width:none}
.aha-page-header--space-between .aha-page-header__field{flex:0 1 320px}
@container aha-page-header (max-width:991px){
  .aha-page-header--space-between .aha-page-header__body{flex-direction:column;align-items:flex-start;gap:var(--aha-space-32)}
  .aha-page-header--space-between .aha-page-header__form{width:100%;max-width:480px}
  .aha-page-header--space-between .aha-page-header__aside{width:100%;max-width:480px}
  .aha-page-header__title{font-size:var(--aha-size-h3)}
}
@container aha-page-header (max-width:479px){
  .aha-page-header__inner{padding:var(--aha-space-48) var(--aha-space-24) 0}
  .aha-page-header--no-tabs .aha-page-header__inner{padding-bottom:var(--aha-space-48)}
  .aha-page-header__title{font-size:var(--aha-size-h4)}
  .aha-page-header__text{font-size:var(--aha-size-l)}
  .aha-page-header__tabs{column-gap:var(--aha-space-16);margin-top:var(--aha-space-32)}
}
